-- ── 1. The bounds: one source of truth, readable by every workspace member (the pages may word a refusal from it) ──────────
CREATE OR REPLACE FUNCTION public.fs_work_bounds()
RETURNS jsonb LANGUAGE sql STABLE SET search_path = pg_catalog, public AS $$
  SELECT jsonb_build_object(
    'contract', 'fs-work-bounds/1',
    'evidenceRowsPerBatch', 1000,
    'evidenceDocumentBytesPerBatch', 1048576,
    'evidenceRowsPerVersion', 3000,
    'reportDocumentBytes', 8388608,
    'versionsPerLineage', 1000,
    'commentsPerVersion', 500,
    'eventsPerComment', 200
  );
$$;
REVOKE ALL ON FUNCTION public.fs_work_bounds() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fs_work_bounds() TO authenticated;

-- ── 2. Evidence batches: rows and bytes per batch ──────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_bound_evidence_batch()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE
  v_b     jsonb := public.fs_work_bounds();
  v_rows  integer;
  v_bytes bigint;
BEGIN
  v_rows := CASE WHEN jsonb_typeof(NEW.batch_document -> 'rows') = 'array' THEN jsonb_array_length(NEW.batch_document -> 'rows') ELSE 0 END;
  IF v_rows > (v_b ->> 'evidenceRowsPerBatch')::integer THEN
    RAISE EXCEPTION 'EVIDENCE_ROWS_LIMIT: the % file has % data rows; at most % rows are accepted in one evidence file (split the file by period or account)',
      NEW.evidence_type, v_rows, v_b ->> 'evidenceRowsPerBatch' USING ERRCODE = '22023';
  END IF;
  v_bytes := octet_length(NEW.batch_document::text);
  IF v_bytes > (v_b ->> 'evidenceDocumentBytesPerBatch')::bigint THEN
    RAISE EXCEPTION 'EVIDENCE_DOCUMENT_SIZE_LIMIT: the % file is % bytes as evidence; at most % bytes are accepted in one evidence file',
      NEW.evidence_type, v_bytes, v_b ->> 'evidenceDocumentBytesPerBatch' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.fs_bound_evidence_batch() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER trg_feb_work_bounds BEFORE INSERT ON public.financial_evidence_batches
  FOR EACH ROW EXECUTE FUNCTION public.fs_bound_evidence_batch();

-- ── 3. Report versions: versions per lineage, document bytes, evidence rows referenced by the version ──────────────────────
CREATE OR REPLACE FUNCTION public.fs_bound_report_version()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE
  v_b     jsonb := public.fs_work_bounds();
  v_bytes bigint;
  v_rows  bigint;
BEGIN
  IF NEW.report_version > (v_b ->> 'versionsPerLineage')::integer THEN
    RAISE EXCEPTION 'VERSION_HISTORY_LIMIT: report % has reached % saved versions, the most one lineage may hold; no further version can be saved on it',
      NEW.report_id, v_b ->> 'versionsPerLineage' USING ERRCODE = '22023';
  END IF;
  v_bytes := octet_length(NEW.report_document::text);
  IF v_bytes > (v_b ->> 'reportDocumentBytes')::bigint THEN
    RAISE EXCEPTION 'REPORT_DOCUMENT_SIZE_LIMIT: the report document is % bytes; at most % bytes are accepted for one version',
      v_bytes, v_b ->> 'reportDocumentBytes' USING ERRCODE = '22023';
  END IF;
  SELECT coalesce(sum(jsonb_array_length(b.batch_document -> 'rows')), 0) INTO v_rows
    FROM public.financial_evidence_batches b
   WHERE b.evidence_batch_id = ANY (coalesce(NEW.evidence_batch_ids, '{}'))
     AND jsonb_typeof(b.batch_document -> 'rows') = 'array';
  IF v_rows > (v_b ->> 'evidenceRowsPerVersion')::bigint THEN
    RAISE EXCEPTION 'EVIDENCE_ROWS_PER_VERSION_LIMIT: the version references % evidence rows; at most % rows of evidence may stand behind one version',
      v_rows, v_b ->> 'evidenceRowsPerVersion' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.fs_bound_report_version() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER trg_fsr_work_bounds BEFORE INSERT ON public.financial_statement_reports
  FOR EACH ROW EXECUTE FUNCTION public.fs_bound_report_version();

-- ── 4. Reviewer comments: comments per version, events per comment ─────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_bound_review_comment()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE
  v_b jsonb := public.fs_work_bounds();
  v_n bigint;
BEGIN
  SELECT count(*) INTO v_n FROM public.fs_review_comments c WHERE c.report_id = NEW.report_id AND c.report_version = NEW.report_version;
  IF v_n >= (v_b ->> 'commentsPerVersion')::bigint THEN
    RAISE EXCEPTION 'REVIEW_COMMENTS_LIMIT: version % of report % already holds % comments, the most one version may hold',
      NEW.report_version, NEW.report_id, v_b ->> 'commentsPerVersion' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.fs_bound_review_comment() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER trg_fsrc_work_bounds BEFORE INSERT ON public.fs_review_comments
  FOR EACH ROW EXECUTE FUNCTION public.fs_bound_review_comment();

CREATE OR REPLACE FUNCTION public.fs_bound_review_comment_event()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE
  v_b jsonb := public.fs_work_bounds();
  v_n bigint;
BEGIN
  SELECT count(*) INTO v_n FROM public.fs_review_comment_events e WHERE e.comment_id = NEW.comment_id;
  IF v_n >= (v_b ->> 'eventsPerComment')::bigint THEN
    RAISE EXCEPTION 'REVIEW_COMMENT_EVENTS_LIMIT: comment % already holds % events, the most one comment may hold',
      NEW.comment_id, v_b ->> 'eventsPerComment' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.fs_bound_review_comment_event() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER trg_fsrce_work_bounds BEFORE INSERT ON public.fs_review_comment_events
  FOR EACH ROW EXECUTE FUNCTION public.fs_bound_review_comment_event();

