     OR NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_fsrce_work_bounds' AND tgrelid = 'public.fs_review_comment_events'::regclass)
     OR has_function_privilege('anon', 'public.fs_work_bounds()', 'EXECUTE')
